package instance_pool

import (
	"reflect"
	"testing"

	v3 "github.com/exoscale/egoscale/v3"
)

const (
	testSubnetFrontID   v3.UUID = "8f3a0000-0000-4000-8000-0000000000a1"
	testSubnetBackID    v3.UUID = "8f3a0000-0000-4000-8000-0000000000b1"
	testSubnetMgmtID    v3.UUID = "8f3a0000-0000-4000-8000-0000000000c1"
	testSubnetDeletedID v3.UUID = "8f3a0000-0000-4000-8000-0000000000d1"
)

func TestFormatPoolVPCSubnets(t *testing.T) {
	// listed in the VPC order, which differs from the pool orders below
	vpcSubnets := []v3.ListSubnetEntry{
		{ID: testSubnetFrontID, Name: "front", Ipv4Block: "10.43.0.0/24"},
		{ID: testSubnetBackID, Name: "back", Ipv4Block: "10.43.1.0/24"},
		{ID: testSubnetMgmtID, Name: "mgmt", Ipv4Block: "10.43.2.0/24"},
	}

	tests := []struct {
		name        string
		poolSubnets []v3.InstancePoolVpcSubnets
		want        []string
	}{
		{
			name:        "follows the pool order",
			poolSubnets: []v3.InstancePoolVpcSubnets{{ID: testSubnetBackID}, {ID: testSubnetFrontID}},
			want:        []string{"back 10.43.1.0/24", "front 10.43.0.0/24"},
		},
		{
			name:        "skips VPC Subnets not in the pool",
			poolSubnets: []v3.InstancePoolVpcSubnets{{ID: testSubnetMgmtID}},
			want:        []string{"mgmt 10.43.2.0/24"},
		},
		{
			name:        "shows the ID of a Subnet missing from the VPC",
			poolSubnets: []v3.InstancePoolVpcSubnets{{ID: testSubnetDeletedID}, {ID: testSubnetFrontID}},
			want:        []string{string(testSubnetDeletedID), "front 10.43.0.0/24"},
		},
		{
			name: "no pool Subnets",
			want: []string{},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := formatPoolVPCSubnets(tt.poolSubnets, vpcSubnets)
			if !reflect.DeepEqual(got, tt.want) {
				t.Fatalf("expected %q, got %q", tt.want, got)
			}
		})
	}
}
